const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',building:'<path d="M4 21V5l8-2v18M12 9h8v12M2 21h20M7 8h2M7 12h2M7 16h2M15 12h2M15 16h2"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 5"/>',layers:'<path d="m12 3 10 5-10 5L2 8l10-5ZM2 12l10 5 10-5M2 16l10 5 10-5"/>',card:'<rect x="2" y="5" width="20" height="14" rx="3"/><path d="M2 10h20M6 15h4"/>',chart:'<path d="M3 3v18h18M7 16l4-5 4 2 5-8"/>',help:'<path d="M3 13v-2a9 9 0 0 1 18 0v2M3 12h3v7H3zM18 12h3v7h-3zM18 19c0 3-3 3-6 3"/>',settings:'<path d="m9 3-1 3-3 1 1 3-2 2 2 2-1 3 3 1 1 3h4l1-3 3-1-1-3 2-2-2-2 1-3-3-1-1-3Z"/><circle cx="11" cy="12" r="3"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Z"/><path d="m8 12 3 3 5-6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',bell:'<path d="M5 17h14l-2-4V9a5 5 0 0 0-10 0v4l-2 4ZM10 21h4"/>',plus:'<path d="M12 5v14M5 12h14"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6M17 2v6M3 11h18"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',dollar:'<path d="M12 2v20M17 6c-6-4-13 4-5 6s1 10-5 6"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.grid}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial=[['Acme Corporation','acme.cgbod.com','Enterprise','Active',128,499,'Oct 24, 2026','A','#eaeaf6'],['Layers Design','layers.cgbod.com','Professional','Active',42,199,'Oct 23, 2026','◈','#efeaf5'],['Sisyphus Ventures','sisyphus.cgbod.com','Professional','Trial',18,199,'Oct 23, 2026','ϟ','#f5eee4'],['Catalog Studio','catalog.cgbod.com','Starter','Active',12,79,'Oct 22, 2026','▧','#e9f0e8'],['Quotient Labs','quotient.cgbod.com','Enterprise','Active',86,499,'Oct 21, 2026','Q','#eeeaf4']].map((a,i)=>({id:i+1,name:a[0],domain:a[1],plan:a[2],status:a[3],users:a[4],mrr:a[5],joined:a[6],logo:a[7],color:a[8]}));
let tenants=JSON.parse(localStorage.getItem('cgbod-tenants')||'null')||initial;let page='Overview',query='',filter='All statuses',period='Monthly';let activities=JSON.parse(localStorage.getItem('cgbod-activity')||'null')||[{text:'Acme Corporation upgraded to Enterprise',detail:'Subscription updated',time:'12 min ago'},{text:'New tenant registered: Layers Design',detail:'Tenant management',time:'38 min ago'},{text:'Invoice #INV-2026-1042 paid',detail:'Payment received · $499.00',time:'1 hour ago'}];
function save(){localStorage.setItem('cgbod-tenants',JSON.stringify(tenants));localStorage.setItem('cgbod-activity',JSON.stringify(activities))}function notify(s){const t=document.querySelector('#toast');t.textContent=s;t.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.style.display='none',3500)}
const navItems=[['Overview','grid'],['Tenants','building'],['Users & roles','users'],['Subscriptions','layers'],['Billing & invoices','card'],['Analytics','chart']];
function render(){document.querySelector('#app').innerHTML=`<aside><div class="brand"><div class="brandmark"><i></i><i></i><i></i><i></i></div><span>cgbod<span style="color:#8da36c">.</span></span></div><div class="edition">SUPER ADMIN</div><div class="navlabel">WORKSPACE</div>${navItems.map(([n,i])=>nav(n,i)).join('')}<div class="navsplit"><div class="navlabel">PLATFORM</div>${nav('Support center','help','4')}${nav('Audit logs','shield')}${nav('Settings','settings')}</div><div class="sidebottom"><div class="helpbox"><strong style="font-size:12px">A little help goes a long way.</strong><p>Find guides and answers to keep<br>your platform running smoothly.</p><button onclick="go('Support center')">Visit help center ↗</button></div><div class="profile"><div class="avatar">AK</div><div><strong>Alex Kim</strong><small>Super administrator</small></div><span>⌄</span></div></div></aside><main><header><div class="breadcrumb">Workspace <span style="color:#c0c6b9">/</span><span>${page}</span></div><div class="topright"><label class="search">${icon('search')}<input placeholder="Search anything..." aria-label="Search tenants globally" onkeydown="if(event.key==='Enter'){query=this.value;go('Tenants',true)}"><kbd>⌘ K</kbd></label><button class="iconbtn" aria-label="Notifications" onclick="notifications()">${icon('bell')}<i class="dot"></i></button><div style="height:22px;border-left:1px solid #eceee7"></div><div class="avatar headeravatar">AK</div></div></header><div class="content"><div class="titlebar"><div><h1>${page==='Overview'?'Platform overview':page}</h1><p class="subtitle">${descriptions[page]||'Understand and manage your platform, all in one place.'}</p></div><div class="actions">${page==='Overview'||page==='Analytics'?`<button class="btn" onclick="dateDialog()">${icon('calendar')} Oct 1 – Oct 31, 2026 <span style="color:#9aa48e">⌄</span></button>`:''}<button class="btn primary" onclick="${page==='Users & roles'?'invite()':page==='Settings'?'saveSettings()':page==='Support center'?'ticket()':'tenantModal()'}">${icon('plus')}${page==='Users & roles'?'Invite user':page==='Settings'?'Save changes':page==='Support center'?'New ticket':'Add tenant'}</button></div></div>${body()}<div class="footer"><span>© 2026 CGBOD. All rights reserved.</span><span>Demo workspace <span style="margin:0 12px">·</span> Last synced just now <span style="color:#89a571">●</span></span></div></div></main>`}
const descriptions={'Overview':"A clear view of your business. Everything you need to keep growing.",'Tenants':'Manage every organization that calls your platform home.','Users & roles':'Manage platform access and administrator permissions.','Subscriptions':'Flexible plans that grow alongside your customers.','Billing & invoices':'Track invoices, payments, and recurring revenue.','Analytics':'Turn platform performance into your next move.','Support center':'Keep your customers moving with thoughtful support.','Audit logs':'A transparent record of activity across your platform.','Settings':'Make CGBOD work the way you do.'};
function nav(n,i,count){return `<button aria-label="${n}" class="nav ${page===n?'active':''}" onclick="go('${n}')">${icon(i)}<span>${n}</span>${n==='Tenants'?`<b>${1248+tenants.length-initial.length}</b>`:count?`<b class="count">${count}</b>`:''}</button>`}function go(p,keep=false){page=p;if(!keep){query='';filter='All statuses'}render();window.scrollTo(0,0)}
function stats(){return `<div class="stats">${[['Total tenants','1,248','+12.8%','vs. last month','building'],['Monthly recurring revenue','$84,254','+18.6%','vs. last month','dollar'],['Active users','24,892','+8.2%','vs. last month','users'],['Trial conversion rate','68.4<small>%</small>','+4.2%','vs. last month','chart']].map((s,i)=>`<div class="card stat ${i===1?'highlight':''}"><div class="statlabel">${s[0]}${icon(s[4])}</div><div class="statvalue">${s[1]}</div><div class="stattrend"><b>↗ ${s[2]}</b> ${s[3]}</div></div>`).join('')}</div>`}
function revenue(){return `<div class="chartrow"><section class="card"><div class="cardhead"><div><h2>Revenue overview</h2><p>Your recurring revenue, moving in the right direction.</p></div><div class="segmented">${['Monthly','Weekly'].map(x=>`<button class="${period===x?'active':''}" onclick="period='${x}';render()">${x}</button>`).join('')}</div></div><div class="legend"><span><i></i>Revenue</span><span><i></i>Previous period</span></div><svg class="chart" viewBox="0 0 620 205" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#b7caa0" stop-opacity=".4"/><stop offset="1" stop-color="#dce7ce" stop-opacity=".04"/></linearGradient></defs>${[0,1,2,3].map((x)=>`<text x="0" y="${27+x*46}">$${90-x*30}k</text><line x1="39" x2="606" y1="${23+x*46}" y2="${23+x*46}"/>`).join('')}<path d="M40 147C70 147 70 118 100 127S140 133 162 113 191 126 220 106 251 112 281 88 306 103 340 73 377 83 400 66 435 73 463 47 486 59 519 36 558 42 603 19V163H40Z" fill="url(#area)"/><path d="M40 152C75 145 70 154 100 143S145 154 163 134 191 144 220 127 260 139 282 115 308 132 341 106 377 121 400 96 438 110 462 83 490 102 520 76 567 91 603 62" stroke="#cddbb8" stroke-width="2" stroke-dasharray="5 4" fill="none"/><path d="M40 147C70 147 70 118 100 127S140 133 162 113 191 126 220 106 251 112 281 88 306 103 340 73 377 83 400 66 435 73 463 47 486 59 519 36 558 42 603 19" fill="none" stroke="#47775a" stroke-width="2.4"/>${(period==='Monthly'?['May','Jun','Jul','Aug','Sep','Oct']:['Week 1','Week 2','Week 3','Week 4']).map((m,i,a)=>`<text x="${40+i*555/(a.length-1)}" y="191">${m}</text>`).join('')}</svg><div class="revenuefoot"><span>Total revenue <strong>$462,890</strong></span><span>Avg. revenue / tenant <strong>$67.51</strong></span></div></section><section class="card"><div class="cardhead"><div><h2>Subscriptions by plan</h2><p>A plan for every stage of growth.</p></div><button class="more" aria-label="View subscription plans" onclick="go('Subscriptions')">···</button></div><div class="donutarea"><div class="donut"><div><strong>1,248</strong><small>Total subscriptions</small></div></div><div class="planlegend">${[['Enterprise','48%','#345e46'],['Professional','28%','#95ad73'],['Starter','16%','#d7e3b4'],['Free','8%','#edf1e4']].map(x=>`<div><i style="background:${x[2]}"></i><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div></div><div class="planfoot"><span><b>↑ 86</b> new subscriptions this month</span><button class="textlink" onclick="go('Subscriptions')">View plans ↗</button></div></section></div>`}
function tenantTable(){const rows=tenants.filter(t=>(t.name+' '+t.domain).toLowerCase().includes(query.toLowerCase())&&(filter==='All statuses'||t.status===filter));return `<section class="card"><div class="tabletop"><div><h2>${page==='Overview'?'Recent tenants':'All tenants'} <span>${page==='Overview'?'Latest 5':tenants.length}</span></h2><p>A growing community. See who’s joined your platform.</p></div><div class="tabletools"><label class="tablesearch">${icon('search')}<input aria-label="Search tenants" placeholder="Search tenants..." value="${esc(query)}" oninput="query=this.value;updateRows()"></label><select aria-label="Filter tenant status" onchange="filter=this.value;updateRows()">${['All statuses','Active','Trial','Suspended'].map(s=>`<option ${filter===s?'selected':''}>${s}</option>`).join('')}</select><button class="btn" onclick="exportData()">${icon('download')}Export</button></div></div><div class="tablewrap"><table><thead><tr><th><input type="checkbox" aria-label="Select all tenants" onchange="document.querySelectorAll('td input').forEach(c=>c.checked=this.checked)"></th><th>Tenant name ↓</th><th>Plan</th><th>Status</th><th>Users</th><th>MRR</th><th>Joined date</th><th></th></tr></thead><tbody id="tenantrows">${rowsHTML(rows)}</tbody></table></div><div class="tablefoot"><span id="rowcount">Showing ${rows.length} of ${tenants.length} tenants</span><div class="pages"><button onclick="notify('You’re on the first page')">‹</button><button class="active">1</button><button onclick="notify('All demo tenants are shown on this page')">›</button></div></div></section>`}
function rowsHTML(rows){return rows.length?rows.map(t=>`<tr><td><input type="checkbox" aria-label="Select ${esc(t.name)}"></td><td><div class="company"><div class="companylogo" style="background:${t.color}">${esc(t.logo)}</div><div><strong>${esc(t.name)}</strong><small>${esc(t.domain)}</small></div></div></td><td><span class="planbadge ${t.plan}">${t.plan}</span></td><td><span class="status ${t.status}"><i></i>${t.status}</span></td><td>${t.users}</td><td style="color:#4b5b42">$${t.mrr}.00</td><td>${t.joined}</td><td><button class="more" aria-label="Manage ${esc(t.name)}" onclick="tenantModal(${t.id})">···</button></td></tr>`).join(''):'<tr><td colspan="8" class="empty">No tenants match your search.</td></tr>'}function updateRows(){const rows=tenants.filter(t=>(t.name+' '+t.domain).toLowerCase().includes(query.toLowerCase())&&(filter==='All statuses'||t.status===filter));document.querySelector('#tenantrows').innerHTML=rowsHTML(rows);document.querySelector('#rowcount').textContent=`Showing ${rows.length} of ${tenants.length} tenants`}
function bottom(){return `<div class="bottomgrid"><section class="card"><div class="cardhead"><h2>Recent activity</h2><button class="textlink" onclick="go('Audit logs')">View all activity ↗</button></div>${activities.slice(0,3).map(a=>`<div class="activity"><div class="activityicon">↗</div><div><p>${esc(a.text)}</p><small>${esc(a.detail)}</small></div><time>${a.time}</time></div>`).join('')}</section><section class="card"><div class="cardhead" style="margin-bottom:8px"><h2>Platform health</h2><span style="font-size:9px;color:#9aa98c">Live status</span></div>${['API & application','Database services','Background workers'].map(s=>`<div class="service"><span>${s}</span><span>● &nbsp; Operational</span></div>`).join('')}<div class="service"><span>Uptime over the last 30 days</span><strong style="font-weight:500">99.98%</strong></div></section></div>`}
function body(){if(page==='Overview')return `<div class="health"><i></i>All systems operational <time>Last checked a few seconds ago</time><a href="#health" onclick="event.preventDefault();document.querySelector('.bottomgrid').scrollIntoView({behavior:'smooth'})">View system status ↗</a></div>${stats()}${revenue()}${tenantTable()}${bottom()}`;if(page==='Tenants')return tenantTable();if(page==='Analytics')return stats()+revenue()+bottom();if(page==='Subscriptions')return `<div class="pagecards">${[['Starter',79,'15 users','Essential tools','Email support'],['Professional',199,'50 users','Advanced analytics','Priority support'],['Enterprise',499,'Unlimited users','Custom integrations','Dedicated account manager']].map((p,i)=>`<section class="card price"><span class="planbadge ${p[0]}">${i===1?'MOST POPULAR':'MONTHLY PLAN'}</span><h2>${p[0]}</h2><div class="statvalue">$${p[1]}<small> / month</small></div><p>✓ ${p[2]}<br>✓ ${p[3]}<br>✓ ${p[4]}<br>✓ Secure cloud storage</p><button class="btn ${i===1?'primary':''}" onclick="query='';go('Tenants');notify('Choose a tenant to manage their plan')">Manage subscriptions ${icon('arrow')}</button></section>`).join('')}</div>${stats()}`;if(page==='Billing & invoices')return stats()+simpleTable(['Invoice','Tenant','Amount','Status','Date',''],tenants.map((t,i)=>[`INV-2026-${1042+i}`,esc(t.name),`$${t.mrr}.00`,'<span class="status"><i></i>Paid</span>','Oct 24, 2026',`<button class="textlink" onclick="downloadInvoice(${t.id})">Download ↓</button>`]));if(page==='Users & roles')return simpleTable(['Name','Email','Role','Status','Last active'],[['Alex Kim','alex@cgbod.com','Super administrator','<span class="status">Active</span>','Just now'],['Sarah Chen','sarah@cgbod.com','Administrator','<span class="status">Active</span>','12 minutes ago'],['James Wilson','james@cgbod.com','Billing manager','<span class="status">Active</span>','2 hours ago'],...JSON.parse(localStorage.getItem('cgbod-invites')||'[]').map(u=>[esc(u.name),esc(u.email),esc(u.role),'<span class="status Trial">Invited</span>','Pending acceptance'])]);if(page==='Audit logs')return simpleTable(['Activity','Category','Actor','Time'],activities.map(a=>[esc(a.text),esc(a.detail),'Alex Kim',a.time]));if(page==='Support center')return simpleTable(['Ticket','Subject','Tenant','Priority','Status'],[['#SUP-104','Help with SSO configuration','Acme Corporation','High','Open'],['#SUP-103','Update billing contact','Layers Design','Normal','Open'],['#SUP-102','Data export request','Catalog Studio','Normal','In progress'],['#SUP-101','API integration question','Quotient Labs','Normal','Open'],...JSON.parse(localStorage.getItem('cgbod-tickets')||'[]').map((t,i)=>['#SUP-'+(105+i),esc(t.subject),esc(t.tenant),esc(t.priority),'Open'])]);if(page==='Settings'){const s=JSON.parse(localStorage.getItem('cgbod-settings')||'{}');return `<section class="card settingsform"><h2 style="font-size:15px;margin:0 0 25px">General settings</h2><label>Platform name<input id="platformname" value="${esc(s.name||'CGBOD')}"></label><label>Support email<input id="supportemail" type="email" value="${esc(s.email||'support@cgbod.com')}"></label><label>Default currency<select id="currency" class="btn">${['USD','SAR','EUR','GBP'].map(c=>`<option ${s.currency===c?'selected':''}>${c}</option>`).join('')}</select></label><label><input type="checkbox" id="registrations" style="display:inline;width:auto" ${s.registrations!==false?'checked':''}> Allow new tenant registrations</label><p style="font-size:11px;color:#8e9885">Preferences are saved locally in this demo workspace.</p><button class="btn primary" onclick="saveSettings()">Save changes</button></section>`}return ''}
function simpleTable(head,rows){return `<section class="card"><div class="tablewrap"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="tablefoot">${rows.length} records · Demo workspace</div></section>`}
function modal(title,description,fields,submit,label='Save changes'){document.querySelector('#modal').innerHTML=`<div class="modalback"><form class="modalbox" onsubmit="event.preventDefault();${submit}"><h2>${title}</h2><p>${description}</p>${fields}<div class="modalactions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button type="submit" class="btn primary">${label}</button></div></form></div>`;document.querySelector('.modalbox input')?.focus()}function closeModal(){document.querySelector('#modal').innerHTML=''}
function tenantModal(id){const t=tenants.find(t=>t.id===id);modal(t?'Manage tenant':'A new place to grow',t?'Update tenant details, subscription, and access.':'Create a new organization on your CGBOD platform.',`<label>Organization name<input id="tname" required maxlength="70" value="${esc(t?.name||'')}" placeholder="e.g. Acme Corporation"></label><label>Subdomain<input id="tdomain" required pattern="[a-z0-9-]+" value="${esc(t?.domain.split('.')[0]||'')}" placeholder="acme"><small>.cgbod.com</small></label><label>Subscription plan<select id="tplan">${['Starter','Professional','Enterprise','Free'].map(p=>`<option ${t?.plan===p?'selected':''}>${p}</option>`).join('')}</select></label><label>Status<select id="tstatus">${['Trial','Active','Suspended'].map(p=>`<option ${t?.status===p?'selected':''}>${p}</option>`).join('')}</select></label>`,`saveTenant(${id||'null'})`,t?'Save changes':'Create tenant')}
function saveTenant(id){const name=document.querySelector('#tname').value.trim(),domain=document.querySelector('#tdomain').value+'.cgbod.com',plan=document.querySelector('#tplan').value,status=document.querySelector('#tstatus').value;if(!name)return;if(tenants.some(t=>t.domain===domain&&t.id!==id)){notify('This subdomain is already in use');return}const t=tenants.find(t=>t.id===id);const data={name,domain,plan,status,mrr:{Starter:79,Professional:199,Enterprise:499,Free:0}[plan]};if(t)Object.assign(t,data);else tenants.unshift({...data,id:Date.now(),users:0,joined:new Date().toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}),logo:name[0].toUpperCase(),color:'#edf1e5'});activities.unshift({text:`${name} ${t?'updated':'joined the platform'}`,detail:'Tenant management · '+plan,time:'Just now'});save();closeModal();render();notify(t?'Tenant updated':'Tenant created successfully')}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}function exportData(){const rows=tenants.filter(t=>(t.name+' '+t.domain).toLowerCase().includes(query.toLowerCase())&&(filter==='All statuses'||t.status===filter));download('cgbod-tenants.csv',[['Name','Domain','Plan','Status','Users','MRR'],...rows.map(t=>[t.name,t.domain,t.plan,t.status,t.users,t.mrr])].map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n'),'text/csv');notify('Tenant export downloaded')}
function downloadInvoice(id){const t=tenants.find(t=>t.id===id);download('cgbod-invoice-'+id+'.txt',`CGBOD — Demo Invoice\nTenant: ${t.name}\nPlan: ${t.plan}\nAmount: USD ${t.mrr}.00\nStatus: Paid\nThis is a sample invoice for the demo workspace.`)}
function invite(){modal('Invite a teammate','Prepare an invitation in this demo workspace.',`<label>Full name<input id="iname" required></label><label>Email address<input type="email" id="iemail" required></label><label>Role<select id="irole"><option>Administrator</option><option>Billing manager</option><option>Support agent</option><option>Viewer</option></select></label>`,'saveInvite()','Create invitation')}function saveInvite(){const users=JSON.parse(localStorage.getItem('cgbod-invites')||'[]');users.push({name:document.querySelector('#iname').value,email:document.querySelector('#iemail').value,role:document.querySelector('#irole').value});localStorage.setItem('cgbod-invites',JSON.stringify(users));closeModal();render();notify('Demo invitation saved. No email was sent.')}
function ticket(){modal('Create support ticket','Keep track of a customer request.',`<label>Subject<input id="subject" required></label><label>Tenant<select id="tickettenant">${tenants.map(t=>`<option>${esc(t.name)}</option>`).join('')}</select></label><label>Priority<select id="priority"><option>Normal</option><option>High</option><option>Low</option></select></label>`,'saveTicket()','Create ticket')}function saveTicket(){const tickets=JSON.parse(localStorage.getItem('cgbod-tickets')||'[]');tickets.push({subject:document.querySelector('#subject').value,tenant:document.querySelector('#tickettenant').value,priority:document.querySelector('#priority').value});localStorage.setItem('cgbod-tickets',JSON.stringify(tickets));closeModal();render();notify('Support ticket created')}
function saveSettings(){const email=document.querySelector('#supportemail');if(!email.checkValidity()){email.reportValidity();return}localStorage.setItem('cgbod-settings',JSON.stringify({name:document.querySelector('#platformname').value,email:email.value,currency:document.querySelector('#currency').value,registrations:document.querySelector('#registrations').checked}));notify('Platform preferences saved')}
function notifications(){modal('You’re up to date','Recent platform notifications.',activities.slice(0,3).map(a=>`<p style="border-bottom:1px solid #eef1e7;padding:12px 0;color:#506447">${esc(a.text)}<br><small style="color:#9aa28f">${a.time}</small></p>`).join(''),'closeModal()','Done')}
function dateDialog(){modal('Reporting period','Overview metrics show sample data for October 2026.',`<label>Period<select><option>October 2026</option></select></label><p>Connect a data source to enable reports for additional periods.</p>`,'closeModal()','Apply')}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();document.querySelector('.search input')?.focus()}});document.querySelector('#modal').addEventListener('click',e=>{if(e.target.classList.contains('modalback'))closeModal()});render();
